import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-03-26","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-03-26","date":"2025-03-26T00:00:00.000Z","updated":"2025-03-27T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","软件重构","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-26.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-26.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-26.md"};function r(n,l,s,p,g,_){return t(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 2025年3月26日<br><strong>参会人员</strong>: Ceph 开发团队成员</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>PR 修复 ETag 响应问题</strong></p><ul><li>讨论了一个修复 ETag 响应中引号问题的 PR。</li><li>决定添加发布说明以修复问题，尽管可能会影响一些客户端。</li><li>后续行动：添加发布说明并进行 QA 测试。</li></ul></li><li><p><strong>RGW 测试套件中的 Lockdep 覆盖率</strong></p><ul><li>讨论了 RGW 测试套件中 Lockdep 的使用情况，发现其未启用。</li><li>决定继续启用 Lockdep，尽管有性能开销的担忧。</li><li>后续行动：合并当前状态并继续观察。</li></ul></li><li><p><strong>Boost 1.87 版本问题</strong></p><ul><li>讨论了在 Ubuntu 上使用 Boost 1.87 时遇到的 Valgrind 错误。</li><li>怀疑是 Boost 版本或配置差异导致的。</li><li>后续行动：进一步调查并确认 Boost 版本问题。</li></ul></li><li><p><strong>RGW 线程池阻塞问题</strong></p><ul><li>讨论了 RGW 中某些 S3 操作会阻塞线程池的问题，导致 RGW 无法接受新连接。</li><li>提出了通过调试日志或性能计数器来跟踪阻塞操作的建议。</li><li>后续行动：创建 Tracker 来跟踪并解决阻塞操作问题。</li></ul></li><li><p><strong>S3 测试套件覆盖率</strong></p><ul><li>讨论了 S3 测试套件的覆盖率，认为某些特殊配置的测试覆盖不足。</li><li>建议通过运行完整的 RGW 测试套件并分析日志来发现阻塞操作。</li></ul></li><li><p><strong>线程池和连接管理</strong></p><ul><li>讨论了 RGW 线程池和连接管理的性能问题，特别是线程池阻塞导致无法接受新连接。</li><li>建议增加性能计数器来跟踪阻塞线程的数量。</li><li>后续行动：增加性能计数器并进一步优化线程池管理。</li></ul></li><li><p><strong>OSD 操作超时问题</strong></p><ul><li>讨论了 OSD 操作超时的问题，可能需要单独的配置选项来处理超时。</li><li>后续行动：跟踪相关 PR 并重新审视 OSD 操作超时问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>修复 ETag 响应问题并添加发布说明。</li><li>继续启用 Lockdep 并观察其性能影响。</li><li>调查 Boost 1.87 版本问题，确认是否使用了错误的 Boost 版本。</li><li>创建 Tracker 来跟踪并解决 RGW 线程池阻塞问题。</li><li>增加性能计数器以跟踪阻塞线程的数量。</li><li>重新审视 OSD 操作超时问题并考虑增加配置选项。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li>添加 ETag 响应修复的发布说明并进行 QA 测试。</li><li>合并 Lockdep 启用状态并继续观察。</li><li>进一步调查 Boost 1.87 版本问题。</li><li>创建 Tracker 来跟踪并解决 RGW 线程池阻塞问题。</li><li>增加性能计数器以跟踪阻塞线程的数量。</li><li>重新审视 OSD 操作超时问题并考虑增加配置选项。</li></ol><p><strong>会议结束</strong></p>',9)])])}const u=i(a,[["render",r]]);export{d as __pageData,u as default};
